//! SQLite bootstrap schema.
use anyhow::Result;
use rusqlite::Connection;
use std::path::Path;
pub fn open_database(path:impl AsRef<Path>)->Result<Connection>{if let Some(p)=path.as_ref().parent(){std::fs::create_dir_all(p)?;}let db=Connection::open(path)?;db.pragma_update(None,"foreign_keys","ON")?;db.busy_timeout(std::time::Duration::from_secs(5))?;migrate(&db)?;Ok(db)}
pub fn migrate(db:&Connection)->Result<()>{db.execute_batch("CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY,applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE IF NOT EXISTS machines(id TEXT PRIMARY KEY,name TEXT NOT NULL,asset_tag TEXT NOT NULL UNIQUE,machine_type TEXT NOT NULL,location TEXT,status TEXT NOT NULL,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS telemetry_samples(id INTEGER PRIMARY KEY AUTOINCREMENT,machine_id TEXT NOT NULL REFERENCES machines(id) ON DELETE CASCADE,metric TEXT NOT NULL,value REAL NOT NULL,unit TEXT NOT NULL,observed_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS idx_telemetry_machine_metric_time ON telemetry_samples(machine_id,metric,observed_at);CREATE TABLE IF NOT EXISTS audit_events(id INTEGER PRIMARY KEY AUTOINCREMENT,actor TEXT NOT NULL,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,details_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);INSERT OR IGNORE INTO schema_migrations(version) VALUES(1);")?;Ok(())}
#[cfg(test)]mod tests{use super::*;#[test]fn creates_schema(){let db=Connection::open_in_memory().unwrap();migrate(&db).unwrap();let n:i64=db.query_row("SELECT COUNT(*) FROM schema_migrations WHERE version=1",[],|r|r.get(0)).unwrap();assert_eq!(n,1);}}
